# Part 2. Checking what the agent read against the file itself (when the file has text). A quantity, a code or a PO
# number the agent handed on that the file does not contain is never trusted: the line is marked for a person.
# ---------------------------------------------------------------------------------------------------------------


def numbers_in(text: str) -> set[float]:
    return {round(float(n), 3) for n in re.findall(r"\d+(?:\.\d+)?", text)}


def squeeze(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", od_text(value).lower())


