# Part 3. Matching products and converting units (unchanged rules, as in 'match and convert').
# ---------------------------------------------------------------------------------------------------------------

UNIT_WORDS = {
    "carton": ["carton", "cartons", "ctn", "ctns", "box", "boxes", "bx", "case", "cases", "cs"],
    "tray": ["tray", "trays", "flat", "flats"],
    "bag": ["bag", "bags", "sack", "sacks"],
    "crate": ["crate", "crates"],
    "each": ["each", "ea", "pc", "pcs", "piece", "pieces", "unit", "units"],
    "kg": ["kg", "kgs", "kilo", "kilos", "kilogram", "kilograms"],
    "bunch": ["bunch", "bunches", "bch", "bn"],
    "punnet": ["punnet", "punnets", "pun", "pnt"],
    "litre": ["litre", "litres", "liter", "liters", "l", "lt", "ltr", "ltrs"],
    "dozen": ["dozen", "dozens", "doz", "dz"],
    "head": ["head", "heads", "hd"],
    "stalk": ["stalk", "stalks", "stick", "sticks"],
}
UNIT_CLASS: dict[str, str] = {}
for unit_class, words in UNIT_WORDS.items():
    for word in words:
        UNIT_CLASS[word] = unit_class
UNIT_CLASS["box"] = "carton"


def unit_class_of(value: Any) -> str:
    word = re.sub(r"[^a-z]", "", od_text(value).lower())
    return UNIT_CLASS.get(word, word)


def same_words(a: str, b: str) -> bool:
    """True when two names differ only by spelling slips, never by a whole word or a number."""
    left = a.split()
    right = b.split()
    if len(left) != len(right):
        return False
    for word in left:
        best = ""
        score = 0.0
        for other in right:
            ratio = 1.0 if word == other else difflib.SequenceMatcher(None, word, other).ratio()
            if ratio > score:
                best = other
                score = ratio
        if any(ch.isdigit() for ch in word):
            if score < 1.0:
                return False
        elif score < 0.75:
            return False
        right.remove(best)
    return True


