                else:
                    needs_review = True
                    flags.append("unit_mismatch")
                    note = (note + " The unit '" + raw_unit + "' could not be converted to " + sell_unit + ".").strip()
                if converted:
                    if match_result == "matched":
                        match_result = "converted"
                    exact = tidy(exact)
                    whole = abs(exact - round(exact)) < 0.0005
                    note = (note + " " + od_text(raw_quantity).rstrip("0").rstrip(".") + " " + raw_unit + " = " + od_text(exact) + " " + sell_unit + (" (pack of " + od_text(pack).rstrip("0").rstrip(".") + " " + base_unit + ")" if pack > 0 else "") + ".").strip()
                    if whole:
                        exact = float(round(exact))
                    else:
                        needs_review = True
                        flags.append("unit_mismatch")
                    if whole:
                        pass
                    elif rounding == "up":
                        exact = float(math.ceil(exact))
                        note += " Rounded up to full selling units."
                    elif rounding == "down":
                        exact = float(math.floor(exact))
                        note += " Rounded down to full selling units."
                    elif rounding == "nearest":
                        exact = float(round(exact))
                        note += " Rounded to the nearest selling unit."
                    else:
                        note += " This is not a whole number of selling units."
                quantity = tidy(exact)
                if own_items and item_code.upper() not in own_items:
                    needs_review = True
                    flags.append("off_catalogue")
                    note = (note + " This product is not on this customer's own list.").strip()
            else:
                flags.append("unknown_product")
                note = "No product matches this line."
            confidence = od_text(one.get("confidence")).lower()
            if confidence not in ("high", "medium", "low"):
                confidence = "medium"
            if confidence == "low":
                needs_review = True
                if "Check against the file" in od_text(one.get("note")):
                    note = (note + " " + od_text(one.get("note"))[od_text(one.get("note")).index("Check against the file"):]).strip()
            line_data: dict[str, Any] = {
                "line_number": line_number,
                "raw_text": raw_text[:500],
                "customer_code": customer_code[:120],
                "raw_unit": raw_unit[:40],
                "line_note": od_text(one.get("note"))[:500],
                "item_code": item_code,
                "quantity": quantity,
                "unit": unit[:40],
                "conversion_note": note[:500],
                "match_result": match_result,
                "read_confidence": confidence,
                "needs_review": needs_review,
            }
            if has_quantity:
                line_data["raw_quantity"] = tidy(raw_quantity)
            links: dict[str, Any] = {"order": [order_id]}
            if product:
                links["product"] = [product["id"]]
            record: dict[str, Any] = {"title": (order_number + " / " + str(line_number)), "data": line_data, "links": links}
            if line_number in existing:
                api.records.update(type_slug="od_order_lines", record_id=existing[line_number]["id"], record=record)
            else:
                api.records.create(type_slug="od_order_lines", record=record)
            lines.append({"line_number": line_number, "item_code": item_code, "quantity": quantity, "unit": unit, "needs_review": needs_review, "note": note, "line_note": od_text(one.get("note")), "raw_text": raw_text})
        flags = sorted(set(flags))
        line_count = len(lines)
        review_count = len([x for x in lines if x["needs_review"]])
        table_rows = ["#;code;qty;unit;check"]
        for x in lines:
            table_rows.append(";".join([str(x["line_number"]), x["item_code"] or "?", str(x["quantity"]), od_text(x["unit"]), ("CHECK " + re.sub(r"[;\s]+", " ", od_text(x["note"]))[:70]).strip() if x["needs_review"] else ""]))
        lines_table = "\n".join(table_rows)
        if len(lines_table) > 2500:
            lines_table = lines_table[:2500] + "\n(cut: every line is saved on the order; lines to check are marked there)"

    # ---- who goes on: the check, or the agent ----
    if not customer_found:
        next = "customer"
        reason = "The customer could not be settled" + (" (" + str(len(candidates)) + " accounts fit)" if candidates else "") + "."
    elif order_notes or order_rules:
        # Notes and rules are words, and whether they bear on this order is a judgement: Jev answers it, and only
        # a confident "nothing to do" lets the order go on without the agent.
        next = "rules"
        reason = "This customer has notes or rules of their own."
        about = "Customer notes: " + (order_notes or "none") + "\nCustomer rules: " + (order_rules or "none") + "\n\nThe order: " + str(line_count) + " lines for " + (known_name or customer_name) + ", PO " + (po_number or "none") + ", delivery " + (delivery_date or "not stated") + ".\nLines (code; quantity; unit):\n" + "\n".join(str(x["line_number"]) + "; " + od_text(x["raw_text"])[:80] for x in lines[:120])
        try:
            said = api.jev.decide(
                question="Do the customer's notes or the customer's rules ask for anything to be changed, swapped, added, held back, flagged or decided on this order?",
                text=about[:6000],
                answers=[
                    {"key": "nothing_to_do", "description": "The notes only describe the customer or how their order form looks (who they are, what their codes look like, that the form is scanned). No note or rule asks for any change, substitution, limit, check or special handling of this order."},
                    {"key": "needs_attention", "description": "At least one note or rule asks for something to be done or checked on this order: a change of quantity, unit or product, a substitution, a minimum or maximum, a delivery instruction, or anything a person or the agent has to decide."},
                ],
                min_confidence=0.9,
            )
            jev_said = od_text(said.get("answer")) or ("unsure: " + od_text(said.get("reason")))
            if od_text(said.get("answer")) == "nothing_to_do" and not said.get("needs_human"):
                next = "check"
                reason = "Jev found that this customer's notes ask for nothing on this order."
        except Exception as error:
            jev_said = "not asked: " + od_text(error)[:120]
    else:
        next = "check"
        reason = "A plain order: no notes or rules apply."
    if next == "check" and "unverified_reading" in flags:
        next = "check_person"
        reason = (unverified + " A person approves this order.").strip()
stated_line_count = line_count
